cat <<'EOF' > app/helpers/time_helper.rb
module TimeHelper
  def time_display_tag(timestamp, format: "relative", **html_options)
    serialized_timestamp = utc_iso8601(timestamp)
    data = (html_options.delete(:data) || {}).merge(time_display_data(format))

    tag.time(serialized_timestamp, datetime: serialized_timestamp, data:, **html_options)
  end

  def date_display_tag(date, format: "calendar-date", **html_options)
    serialized_date = date.to_date.iso8601
    data = (html_options.delete(:data) || {}).merge(time_display_data(format))

    tag.time(serialized_date, datetime: serialized_date, data:, **html_options)
  end

  def time_display_placeholder(timestamp, format: "relative")
    "{{time:#{format}:#{utc_iso8601(timestamp)}}}"
  end

  private
    def time_display_data(format)
      { controller: "time-display", time_display_format_value: format }
    end

    def utc_iso8601(timestamp)
      timestamp = timestamp.to_time.utc
      timestamp.iso8601(timestamp.nsec.zero? ? 0 : 6)
    end
end
EOF
cat <<'EOF' > app/javascript/helpers/date_helpers.js
const MILLISECONDS_PER_DAY = 24 * 60 * 60 * 1000
const RELATIVE_DAY_LIMIT = 6
const TIME_PLACEHOLDER_PATTERN = /\{\{time:([\w-]+):([^}]+)\}\}/g

const timeFormatter = new Intl.DateTimeFormat("en-US", {
  hour: "numeric",
  minute: "2-digit"
})
const shortDateFormatter = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric"
})
const dateWithYearFormatter = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  year: "numeric"
})
const calendarDateFormatter = new Intl.DateTimeFormat("en-US", {
  weekday: "long",
  month: "long",
  day: "numeric"
})
const dateTimeFormatter = new Intl.DateTimeFormat("en-US", {
  month: "numeric",
  day: "numeric",
  year: "2-digit",
  hour: "numeric",
  minute: "2-digit"
})

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / MILLISECONDS_PER_DAY)
}

export function beginningOfDay(date) {
  return new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()))
}

export function formatTimestamp(timestamp, format = "relative", now = new Date()) {
  const date = parseTimestamp(timestamp)

  if (Number.isNaN(date.getTime())) return String(timestamp ?? "")

  switch (format) {
    case "time":
      return timeFormatter.format(date)
    case "date":
      return formatShortDate(date, now)
    case "calendar-date":
      return calendarDateFormatter.format(date)
    case "date-time":
      return dateTimeFormatter.format(date)
    case "relative":
    default:
      return formatRelativeDate(date, now)
  }
}

export function formatTimePlaceholders(text, now = new Date()) {
  if (typeof text !== "string") return text

  return text.replace(TIME_PLACEHOLDER_PATTERN, (_match, format, timestamp) => {
    return formatTimestamp(timestamp, format, now)
  })
}

function parseTimestamp(timestamp) {
  const calendarDate = typeof timestamp === "string" && timestamp.match(/^(\d{4})-(\d{2})-(\d{2})$/)

  if (calendarDate) {
    return new Date(Number(calendarDate[1]), Number(calendarDate[2]) - 1, Number(calendarDate[3]))
  }

  return new Date(timestamp)
}

function formatRelativeDate(date, now) {
  const daysFromNow = signedDifferenceInDays(now, date)

  if (daysFromNow === 0) {
    return timeFormatter.format(date)
  } else if (daysFromNow === -1) {
    return "yesterday"
  } else if (daysFromNow === 1) {
    return "tomorrow"
  } else if (Math.abs(daysFromNow) <= RELATIVE_DAY_LIMIT) {
    return daysFromNow < 0 ? `${Math.abs(daysFromNow)} days ago` : `in ${daysFromNow} days`
  } else {
    return formatShortDate(date, now)
  }
}

function formatShortDate(date, now) {
  return date.getFullYear() === now.getFullYear() ? shortDateFormatter.format(date) : dateWithYearFormatter.format(date)
}
EOF
