module CurrentTimezone
  extend ActiveSupport::Concern

  included do
    around_action :set_current_timezone

    helper_method :timezone_from_cookie

  end

  private
    def set_current_timezone(&)
      Time.use_zone(timezone_from_cookie, &)
    end

    def timezone_from_cookie
      @timezone_from_cookie ||= begin
        timezone = cookies[:timezone]
        ActiveSupport::TimeZone[timezone] if timezone.present?
      end
    end
end
module TimeHelper
  def time_display_tag(timestamp, format: "relative", **html_options)
    serialized_timestamp = utc_iso8601(timestamp)
    data = (html_options.delete(:data) || {}).merge(time_display_data(format))

    tag.time(serialized_timestamp, datetime: serialized_timestamp, data:, **html_options)
  end

  def date_display_tag(date, format: "calendar-date", **html_options)
    serialized_date = date.to_date.iso8601
    data = (html_options.delete(:data) || {}).merge(time_display_data(format))

    tag.time(serialized_date, datetime: serialized_date, data:, **html_options)
  end

  def time_display_placeholder(timestamp, format: "relative")
    "{{time:#{format}:#{utc_iso8601(timestamp)}}}"
  end

  private
    def time_display_data(format)
      { controller: "time-display", time_display_format_value: format }
    end

    def utc_iso8601(timestamp)
      timestamp = timestamp.to_time.utc
      timestamp.iso8601(timestamp.nsec.zero? ? 0 : 6)
    end
end
import { Controller } from "@hotwired/stimulus"
import { formatTimestamp } from "helpers/date_helpers"

export default class extends Controller {
  static values = { format: { type: String, default: "relative" } }

  connect() {
    this.#render()
    this.observer = new MutationObserver(() => this.#render())
    this.observer.observe(this.element, { attributes: true, attributeFilter: [ "datetime" ] })
  }

  disconnect() {
    this.observer.disconnect()
  }

  formatValueChanged() {
    this.#render()
  }

  #render() {
    this.element.textContent = formatTimestamp(this.element.dateTime, this.formatValue)
  }
}
"
}

