  "output": "module TimeHelper
  def time_display_tag(timestamp, format: "relative", **html_options)
    serialized_timestamp = utc_iso8601(timestamp)
    data = (html_options.delete(:data) || {}).merge(time_display_data(format))

    tag.time(serialized_timestamp, datetime: serialized_timestamp, data:, **html_options)
  end

  def date_display_tag(date, format: "calendar-date", **html_options)
    serialized_date = date.to_date.iso8601
    data = (html_options.delete(:data) || {}).merge(time_display_data(format))

    tag.time(serialized_date, datetime: serialized_date, data:, **html_options)
  end

  def time_display_placeholder(timestamp, format: "relative")
    "{{time:#{format}:#{utc_iso8601(timestamp)}}}"
  end

  private
    def time_display_data(format)
      { controller: "time-display", time_display_format_value: format }
    end

    def utc_iso8601(timestamp)
      timestamp = timestamp.to_time.utc
      precision = if timestamp.nsec.zero?
        0
      elsif timestamp.nsec % 1_000 == 0
        6
      else
        9
      end
      timestamp.iso8601(precision)
    end
end
const MILLISECONDS_PER_DAY = 24 * 60 * 60 * 1000
const RELATIVE_DAY_LIMIT = 6
const TIME_PLACEHOLDER_PATTERN = /\{\{time:([\w-]+):([^}]+)\}\}/g

const timeFormatter = new Intl.DateTimeFormat("en-US", {
  hour: "numeric",
  minute: "2-digit"
})
const shortDateFormatter = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric"
})
const dateWithYearFormatter = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  year: "numeric"
})
const calendarDateFormatter = new Intl.DateTimeFormat("en-US", {
  weekday: "long",
  month: "long",
  day: "numeric"
})
const dateTimeFormatter = new Intl.DateTimeFormat("en-US", {
  month: "numeric",
  day: "numeric",
  year: "2-digit",
  hour: "numeric",
  minute: "2-digit"
})

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / MILLISECONDS_PER_DAY)
}

export function beginningOfDay(date) {
  return new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()))
}

export function formatTimestamp(timestamp, format = "relative", now = new Date()) {
  const date = parseTimestamp(timestamp)

  if (Number.isNaN(date.getTime())) return String(timestamp ?? "")

  switch (format) {
    case "time":
      return timeFormatter.format(date)
    case "date":
      return formatShortDate(date, now)
    case "calendar-date":
      return calendarDateFormatter.format(date)
    case "date-time":
      return dateTimeFormatter.format(date)
    case "relative":
    default:
      return formatRelativeDate(date, now)
  }
}

export function formatTimePlaceholders(text, now = new Date()) {
  if (typeof text !== "string") return text

  return text.replace(TIME_PLACEHOLDER_PATTERN, (_match, format, timestamp) => {
    return formatTimestamp(timestamp, format, now)
  })
}

function parseTimestamp(timestamp) {
  const calendarDate = typeof timestamp === "string" && timestamp.match(/^(\d{4})-(\d{2})-(\d{2})$/)

  if (calendarDate) {
    return new Date(Number(calendarDate[1]), Number(calendarDate[2]) - 1, Number(calendarDate[3]))
  }

  return new Date(timestamp)
}

function formatRelativeDate(date, now) {
  const daysFromNow = signedDifferenceInDays(now, date)

  if (daysFromNow === 0) {
    return timeFormatter.format(date)
  } else if (daysFromNow === -1) {
    return "yesterday"
  } else if (daysFromNow === 1) {
    return "tomorrow"
  } else if (Math.abs(daysFromNow) <= RELATIVE_DAY_LIMIT) {
    return daysFromNow < 0 ? `${Math.abs(daysFromNow)} days ago` : `in ${daysFromNow} days`
  } else {
    return formatShortDate(date, now)
  }
}

function formatShortDate(date, now) {
  return date.getFullYear() === now.getFullYear() ? shortDateFormatter.format(date) : dateWithYearFormatter.format(date)
}
import { Controller } from "@hotwired/stimulus"
import { formatTimestamp } from "helpers/date_helpers"

export default class extends Controller {
  static values = { format: { type: String, default: "relative" } }

  connect() {
    this.#render()
    this.observer = new MutationObserver(() => this.#render())
    this.observer.observe(this.element, { attributes: true, attributeFilter: [ "datetime" ] })
  }

  disconnect() {
    this.observer.disconnect()
  }

  formatValueChanged() {
    this.#render()
  }

  #render() {
    this.element.textContent = formatTimestamp(this.element.dateTime, this.formatValue)
  }
}
import { BridgeComponent } from "@hotwired/hotwire-native-bridge"
import { formatTimePlaceholders } from "helpers/date_helpers"

export default class extends BridgeComponent {
  static component = "share"

  shareUrl() {
    const description = formatTimePlaceholders(this.bridgeElement.bridgeAttribute("share-description"))

    this.send("shareUrl", {
      title: document.title,
      url: window.location.href,
      description: description
    })
  }
}
import { BridgeComponent } from "@hotwired/hotwire-native-bridge"
import { formatTimePlaceholders } from "helpers/date_helpers"

export default class extends BridgeComponent {
  static component = "stamp"
  static values = { scopeSelector: { type: String, default: "body" } }

  connect() {
    super.connect()

    if (this.element.closest(this.scopeSelectorValue)) {
      this.notifyBridgeOfConnect()
      this.#observeStamp()
    }
  }

  disconnect() {
    super.disconnect()
    this.notifyBridgeOfDisconnect()
    this.stampObserver?.disconnect()
  }

  notifyBridgeOfConnect() {
    const bridgeElement = this.bridgeElement

    this.send("connect", {
      title: bridgeElement.title,
      description: formatTimePlaceholders(bridgeElement.bridgeAttribute("description"))
    })
  }

  notifyBridgeOfDisconnect() {
    this.send("disconnect")
  }

  #observeStamp() {
    this.stampObserver = new MutationObserver(() => {
      this.notifyBridgeOfConnect()
    })

    this.stampObserver.observe(this.element, {
      attributes: true
    })
  }
}
require "test_helper"

class TimeHelperTest < ActionView::TestCase
  include BridgeHelper

  test "time display tags are identical in every server timezone" do
    timestamp = Time.utc(2025, 9, 12, 20, 42)

    rendered = [ "UTC", "America/Los_Angeles" ].map do |timezone|
      Time.use_zone(timezone) { time_display_tag(timestamp.in_time_zone(timezone)) }
    end

    assert_equal rendered.first, rendered.last
    assert_includes rendered.first, 'datetime="2025-09-12T20:42:00Z"'
    assert_includes rendered.first, 'data-time-display-format-value="relative"'
    assert_includes rendered.first, ">2025-09-12T20:42:00Z</time>"
  end

  test "calendar dates are emitted as date-only values" do
    rendered = date_display_tag(Date.new(2025, 9, 12))

    assert_includes rendered, 'datetime="2025-09-12"'
    assert_includes rendered, 'data-time-display-format-value="calendar-date"'
    assert_includes rendered, ">2025-09-12</time>"
  end

  test "bridge placeholders contain the same UTC timestamp as display tags" do
    timestamp = Time.utc(2025, 9, 12, 20, 42)

    rendered = [ "UTC", "America/Los_Angeles" ].map do |timezone|
      Time.use_zone(timezone) { time_display_placeholder(timestamp, format: "date") }
    end

    assert_equal "{{time:date:2025-09-12T20:42:00Z}}", rendered.first
    assert_equal rendered.first, rendered.last
  end

  test "bridge share descriptions defer timestamp formatting to the browser" do
    card = cards(:logo)
    card.stubs(:assignees).returns([])

    rendered = [ "UTC", "America/Los_Angeles" ].map do |timezone|
      Time.use_zone(timezone) { bridge_share_card_description(card) }
    end

    assert_equal rendered.first, rendered.last
    assert_includes rendered.first, time_display_placeholder(card.created_at, format: "date")
    assert_includes rendered.first, time_display_placeholder(card.last_active_at, format: "date")
  end
end
require "test_helper"

class CurrentTimezoneTest < ActionDispatch::IntegrationTest
  test "does not vary the ETag by timezone cookie" do
    cookies[:timezone] = "America/New_York"
    get user_avatar_path(users(:kevin))
    etag = response.headers.fetch("ETag")

    get user_avatar_path(users(:kevin)), headers: { "If-None-Match" => etag }
    assert_equal 304, response.status

    cookies[:timezone] = "America/Los_Angeles"
    get user_avatar_path(users(:kevin)), headers: { "If-None-Match" => etag }
    assert_equal 304, response.status
    assert_equal etag, response.headers.fetch("ETag")
  end
end
